<script setup lang="ts">
import EventLifecycle from './EventLifecycle.vue';
import EventReadState from './EventReadState.vue';
import {ref,watch} from 'vue';import {post,safeOfficialUrl} from '../api/client';import {title,sourceName,time,type Row} from '../presentation/zh';
const transmissionAvailable=location.port==='5180';const props=defineProps<{id:string;token?:string}>();const data=ref<Row>(),error=ref(''),busy=ref(false);
const statuses:Record<string,string>={VERIFIED:'已核实',PENDING:'待审核',FIELD_MATCHED:'字段一致',SOURCE_CHECKED:'官方来源已核查',INDEPENDENT_SUPPORTED:'独立证据支持',EXTRACTED:'已提取待核实',INSUFFICIENT:'证据不足',CONFLICT:'存在冲突',REJECTED:'已否决',REVISED:'已修订',EXPIRED:'已失效'};
async function analyze(factId:string){if(busy.value)return;busy.value=true;error.value='';try{await post('/impact/analyze',props.token||'',{factId,asOf:new Date().toISOString()});data.value=await post<Row>('/ui/research-detail',props.token||'',{id:props.id});}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
const status=(s:string)=>statuses[s]||'状态待核查';
watch(()=>props.id,async id=>{data.value=undefined;error.value='';busy.value=true;try{const r=await post<Row>('/ui/research-detail',props.token||'',{id});if(!r.event)throw Error('事件不存在或当前许可不允许展示');data.value=r;}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}},{immediate:true});
</script>
<template><section class="panel feed event-research-detail" aria-label="金融事件研究详情"><h2>金融事件研究详情</h2><a v-if="transmissionAvailable" :href="'#/linkage?event='+id">进入S66影响传导研究</a><p v-if="busy" role="status">正在读取事件及原始证据…</p><p v-if="error" role="alert">{{error}}</p><template v-if="data"><p>实际查询时间：{{time(data.queried_at)}}（北京时间）</p><section><h3>事件基本信息</h3><h4>{{title(data.event).text}}</h4><EventReadState :id="data.event.id" :version="data.event.collected_at"/><p>阅读状态保存在当前浏览器；证据版本变化后重新显示未读，不代表实时通知或跨设备同步。</p><p>{{title(data.event).status}} · {{sourceName(data.event.source_id,data.event.publisher)}} · {{data.event.category}}</p><details open><summary>查看原文</summary><p class="original">{{data.event.original_title}}</p></details><p>官方发布时间：{{time(data.event.published_at,'官方发布时间未知')}}<br>首次发现时间：{{time(data.event.first_seen_at)}}<br>实际采集时间：{{time(data.event.collected_at)}}<br>实际入库时间：{{time(data.event.ingested_at)}}</p><p>来源等级：{{data.event.level}}；原始证据状态：{{status(data.event.verification_status)}}。来源确认不等同全部实质事实已核实。</p></section>
<section><h3>关键事实与宏观指标</h3><p v-if="!data.facts.length">尚无可展示的真实原子事实。</p><article v-for="f in data.facts" :key="f.id"><p>事实状态：{{status(f.current_status)}} · 事实版本 {{f.version}}</p><p v-if="f.fields.actual_value!==undefined">原始金融数值：{{f.fields.actual_value??'原始缺失值'}}；单位：{{f.fields.unit||'原文未提供'}}；观测期：{{f.fields.observation_date||f.fields.observation_period||'未提供'}}</p><button v-if="['FIELD_MATCHED','INDEPENDENT_SUPPORTED'].includes(f.current_status)" :disabled="busy" @click="analyze(f.id)">生成证据约束的影响研究</button><details><summary>核对事实字段与原文定位</summary><pre>{{JSON.stringify(f.fields,null,2)}}</pre><article v-for="p in f.evidence" :key="p.evidence_id"><blockquote>{{p.excerpt}}</blockquote><p>证据位置：{{p.source_locator}} · 证据ID：{{p.evidence_id}}</p><a v-if="safeOfficialUrl(p.source_url)" :href="p.source_url" target="_blank" rel="noopener">查看事实官方证据</a></article></details></article><p v-if="!data.observations.length">暂无可核验的宏观指标关联</p><p v-for="m in data.observations" :key="m.id">指标代码 {{m.series_id}} · 观测期 {{m.observation_date}} · 原始值 {{m.value??'缺失'}} · 本地版本 {{m.version}} · <a :href="'#/macro?series='+encodeURIComponent(m.series_id)">查看宏观变化与计算依据</a></p></section>
<section><h3>研究分析与反面证据</h3><p>规则研究优先级不等同市场重要性。宏观假设须结合真实敞口、预期与后续披露核验。</p><p v-if="!data.assessments.length">尚无此事件的有证据规则研判。标题本身不足以证明金融影响。</p><article v-for="a in data.assessments" :key="a.id"><p>规则版本 {{a.rule_version}} · 分析截止 {{time(a.as_of)}} · 输入证据 {{a.input_evidence_id}}</p><details><summary>研究结论、正反假设与不确定性（规则观点）</summary><pre>{{JSON.stringify(a.report,null,2)}}</pre></details></article><p>反向解释：相邻观测与同时发生不能证明因果，已有预期及其他因素可能解释变化。</p><p>继续调查：真实企业敞口、后续官方披露、同口径修订、合法行情与一致预期。</p><p v-if="!data.ai.some((a:Row)=>a.status==='COMPLETED')">人工智能分析：尚无真实模型完成记录。</p><article v-for="a in data.ai.filter((a:Row)=>a.status==='COMPLETED')" :key="a.analysis_id"><p>模型 {{a.model_id}} · 提示版本 {{a.prompt_version}} · 完成 {{time(a.finished_at)}} · 机器观点待审核</p><p>{{a.summary}}</p></article></section>
<section><h3>企业与市场关系</h3><p v-if="!data.entities.length">尚无该事件的实体绑定证据。</p><p v-for="n in data.entities" :key="n.id">{{n.chinese_name||n.official_name}} · 实体 {{status(n.entity_status)}} · 事件关联 {{status(n.link_status)}} · {{n.match_basis}}</p><p v-if="!data.relations.length">尚无该事件的已核实企业关系；产业关联待核验。</p><p v-for="r in data.relations" :key="r.id">关系 {{status(r.status)}} · {{r.explanation}} · 证据 {{r.evidence_id||'缺失'}}</p><p>市场反应：尚未获得合法行情验证。</p></section>
<EventLifecycle :id="props.id" :token="props.token"/><section class="proof"><h3>证据与审计时间线</h3><p>事件ID {{data.event.id}}；原始标题与历史版本保持完整。最多展示100个证据版本。</p><article v-for="r in data.evidence" :key="r.id"><p>原始证据ID {{r.id}} · 数据版本 {{r.revision}} · 哈希{{r.hash_passed?'通过':'失败'}}</p><p>官方发布 {{time(r.published_at,'未知')}} · 采集 {{time(r.collected_at)}} · 入库 {{time(r.ingested_at)}}</p><p>采集任务 {{r.job_id}}</p><code>{{r.raw_content_hash}}</code><p><a v-if="safeOfficialUrl(r.source_url)" :href="r.source_url" target="_blank" rel="noopener">查看原始来源</a></p></article></section></template></section></template>
<style scoped>pre{white-space:pre-wrap;overflow-wrap:anywhere}section,article,code{overflow-wrap:anywhere}section{margin-top:20px}code{word-break:break-all}.proof{border:1px solid var(--line);padding:16px}</style>

